24	  backdropFilter: 'blur(16px) saturate(130%)',
25	  WebkitBackdropFilter: 'blur(16px) saturate(130%)',
26	  border: '1px solid rgba(255,255,255,0.7)',
27	  boxShadow: '0 12px 32px rgba(4,13,109,0.10), inset 0 1px 0 rgba(255,255,255,0.95)',
