42	  const s = STATUS_MAP[status] ?? STATUS_MAP.upcoming;
43	  return (
44	    <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '4px 9px', borderRadius: 8, background: s.bg, color: s.fg, fontWeight: 600, fontSize: 9.5, letterSpacing: '0.06em', textTransform: 'uppercase' }}>
45	      <span style={{ width: 6, height: 6, borderRadius: 999, background: s.dot, flexShrink: 0 }} />
46	      {s.label}
47	    </div>
